import{_ as l,l as i,o as e,c as o,v as t,p as s,x as r,d as E,i as B,S as L}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"NVLM","description":"","frontmatter":{"title":"NVLM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/nvlm.md","filePath":"llm/nvlm.md","lastUpdated":1789023840000}'),p={name:"llm/nvlm.md"};function V(d,a,m,A,h,M){const n=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="nvlm" tabindex="-1">NVLM <a class="header-anchor" href="#nvlm" aria-label="Permalink to &quot;NVLM&quot;">​</a></h1><div class="epigraph"><p>同一套视觉通路上并排放解码器、交叉注意力与混合三种接法；数据质量比堆规模更决定多模态上限，而文本能力要靠显式回放，不能指望冻住骨干就自动保住。</p><footer>—— Dai 等，NVLM: Open Frontier-Class Multimodal LLMs，arXiv:2409.11402</footer></div><p>NVIDIA 2024 年 9 月公开 <strong>NVLM 1.0</strong>：默认骨干是 <strong>Qwen2-72B-Instruct</strong> 加冻结的 <strong>InternViT-6B-448px-V1-5</strong>，在同一数据混合上训练三种接法——解码器专用的 <strong>NVLM-D</strong>、门控交叉注意力的 <strong>NVLM-X</strong>、把缩略图走自注意力、高分辨率格走交叉注意力的 <strong>NVLM-H</strong>。主张不是再发明一种注意力核，而是把 LLaVA 式早拼接与 Flamingo 式交叉注意放在同一实验台上比吞吐、OCR 与推理，并声称多模态训练之后纯文本数学与代码相对骨干还涨了约 4.3 分。本篇按 arXiv:2409.11402 写；权重当时放出的是 Hugging Face 上的 <strong>NVLM-D-72B</strong>，不要把 34B 消融骨干或未公开的 X/H 检查点写成同一天下载包。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源多模态在 2024 年秋天的缺口很具体。一边是解码器专用模型把全部视觉 token 铺进语言模型，OCR 与联合推理强，高分辨率一开序列爆炸、训练吞吐掉下去。一边是交叉注意力把图像留在侧路，吞吐友好，却常靠冻结 LLM 来保文本，视觉指令跟不上；Llama 3-V 那条冻骨干的路当时还没放权重。专有模型（GPT-4o）给人的产品印象是<strong>同一张网既能看图又能写代码</strong>，开源对照则经常「视觉榜好看、MMLU / HumanEval 被洗掉」。NVLM 要同时回答三件事：动态高分辨率怎么标格；D 与 X 各自赢在哪、H 能否折中；文本回放要不要做成一等数据，而不是指望门控在推理时关掉交叉层。</p><h3 id="动态切格缺的是标签-不是再多一个-vit" tabindex="-1">动态切格缺的是标签，不是再多一个 ViT <a class="header-anchor" href="#动态切格缺的是标签-不是再多一个-vit" aria-label="Permalink to &quot;动态切格缺的是标签，不是再多一个 ViT&quot;">​</a></h3><p>视觉通路三家共用：InternViT 以 \\(448^2\\) 为格，最多 <strong>6 块</strong>加一张缩略图，长宽比取 \\(\\{1{:}1,\\ldots,6{:}1\\}\\) 等组合；每格 1024 个 patch，再 <strong>pixel shuffle</strong> 收到 256。这与 <a href="/llm/internvl2">InternVL2</a> / <a href="/llm/anyres">AnyRes</a> 同类。论文额外消融的是：无标签拼接会让「2×3 与 3×2、第几格是哪一块」对解码器不可见；二维坐标标签泛化弱；<strong>一维 <code>&lt;tile_k&gt;</code></strong> 插在该格视觉 token 之前，OCR（ChartQA、DocVQA、OCRBench）与部分推理同时最好。标签是给语言模型读的文本符号，不是给 ViT 的二维位置编码。</p><p><span class="marginnote">编码器全程冻结。论文写过：弱 ViT 时联合训 MLP 与视觉塔有收益；换成 InternViT-6B-V1-5 之后增益变薄，于是为简单起见冻住。不要把 NVLM 写成「端到端解开 ViT」的对照实验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>NVLM-D：缩略图与各格经 MLP 投到 LLM 宽度，与文本拼成一条，满自注意力。预训练只训随机初始化的 MLP，冻 ViT 与 LLM；SFT 解开 MLP 与 LLM。这是 LLaVA 系，只是视觉前缀因 DHR 变得很长。NVLM-X：去掉 Flamingo / <a href="/llm/idefics">IDEFICS</a> 的 Perceiver，认为重采样破坏文档空间关系；门控交叉注意力读各格，tile 标签接到文本侧。NVLM-H：缩略图进自注意力，提供全局与跨模态推理；其余格走交叉注意力，换细粒度、少占解码器长度。34B 消融用 Nous-Hermes-2-Yi-34B 加速，主结果仍钉 Qwen2-72B。</p><h3 id="生产级多模态是数据主张" tabindex="-1">生产级多模态是数据主张 <a class="header-anchor" href="#生产级多模态是数据主张" aria-label="Permalink to &quot;生产级多模态是数据主张&quot;">​</a></h3><p>论文把 GPT-4o 那种「图文任务与纯文本任务都能打」叫做 production-grade multimodality。NVLM-X 可以像 Flamingo 那样冻 LLM、只训交叉层，文本不掉，但视觉指令会让步。他们最终选择：SFT <strong>解开 LLM</strong>，同时混入高质量纯文本，使 D/X/H 在文本数学与代码上相对骨干不降、甚至上升。主张是<strong>数据质量与任务多样性重于堆预训规模</strong>，三套结构共用同一混合，差异才归因于接法。Megatron-Core 训练代码与 D-72B 权重按论文开放；不要假设 X 与 H 的 72B 当时一并上架。</p>',12)),(e(),s(L,null,{default:r(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E8%BE%93%E5%85%A5%E5%9B%BE%E5%83%8F%22%5D%20--%3E%20DHR%5B%22%E5%8A%A8%E6%80%81%E5%88%87%20448%20%E6%A0%BC%20%2B%20%E7%BC%A9%E7%95%A5%E5%9B%BE%22%5D%0A%20%20DHR%20--%3E%20VIT%5B%22%E5%86%BB%E7%BB%93%20InternViT-6B%22%5D%0A%20%20VIT%20--%3E%20PS%5B%22pixel%20shuffle%20%E6%AF%8F%E6%A0%BC%20256%22%5D%0A%20%20PS%20--%3E%20TAG%5B%221-D%20tile%20%E6%A0%87%E7%AD%BE%22%5D%0A%20%20TAG%20--%3E%20D%5B%22NVLM-D%3A%20%E5%85%A8%E9%83%A8%E8%BF%9B%E8%87%AA%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20TAG%20--%3E%20X%5B%22NVLM-X%3A%20%E9%97%A8%E6%8E%A7%E4%BA%A4%E5%8F%89%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20TAG%20--%3E%20H%5B%22NVLM-H%3A%20%E7%BC%A9%E7%95%A5%E5%9B%BE%E8%87%AA%E6%B3%A8%E6%84%8F%20%2F%20%E6%A0%BC%E4%BA%A4%E5%8F%89%E6%B3%A8%E6%84%8F%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%20%2B%20%E6%96%87%E6%9C%AC%20SFT%20%E5%9B%9E%E6%94%BE%22%5D%20--%3E%20D%0A%20%20TXT%20--%3E%20X%0A%20%20TXT%20--%3E%20H%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>解码器专用把视觉与文本放进同一套 \\(QK^\\top\\)，图表里的数和题目里的符号可以在同一层里对齐，这是 OCR 与「看表写代码」涨点的物理原因；代价是序列按格数线性涨，KV 与训练吞吐按平方变差。交叉注意力把图像当记忆、文本当查询，解码器长度近似纯文本，高分辨率更便宜；空间结构若再经 Perceiver 压扁，文档任务先受伤，故 NVLM-X 选择不压。混合结构把「全局该进联合推理」和「局部细节只需被读」拆开：缩略图短、必须进自注意力；多格长、适合侧路。tile 标签则让模型在切格之后仍能用语言点名「第 k 块」，否则注意力只看见一袋 256 维块。</p><h3 id="和冻骨干、和-pixtral-切法不是同一旋钮" tabindex="-1">和冻骨干、和 Pixtral 切法不是同一旋钮 <a class="header-anchor" href="#和冻骨干、和-pixtral-切法不是同一旋钮" aria-label="Permalink to &quot;和冻骨干、和 Pixtral 切法不是同一旋钮&quot;">​</a></h3><p>Llama 3-V 冻 LLM 保文本，是用容量换不掉点；NVLM 用文本回放换解冻后的指令跟随。不要把「文本不掉」写成同一种机制。<a href="/llm/pixtral-paper">Pixtral</a> 从零训可变分辨率 ViT 加 RoPE-2D，格的语义在编码器里；NVLM 的格是冻结 448 编码器加语言模型可读的一维标签。MMMU、OCRBench 谁高取决于协议与切格预算，不能只抄论文雷达图的一圈。</p><p><span class="marginnote">论文对照 Llama 3-V 70B/405B 时写明：对方冻骨干故文本不降，NVLM-D-72B 则在解冻后靠文本数据把数学与代码平均准确率抬高约 4.3 分。引用「多模态训练提升纯文本」必须带上「混了文本 SFT」，否则会读成视觉数据本身在教数学。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>公开主卡是 D-72B，服务应按「最多 6 格 + 缩略图 × 256 token」预留预填充，而不是按平均图尺寸配卡。X/H 的交叉层是额外参数，论文拿 Llama 3-V 405B 加了约 100B 交叉参数当反例：侧路不是免费。编码器 448 固定，极细字仍靠加格，不是原生动态 patch。评测对标 GPT-4o、Llama 3-V、InternVL2，数字是该报告协议，不要和各家博客峰值混行。</p><p>不要把 NVLM-H 写成「把 D 和 X 的权重平均」。不要把 Qwen2-72B 的许可与 NVIDIA 放出的检查点许可混成一张卡；再分发前读模型卡。32B 以下的故事不在这篇主文里。测试期若把格数加到训练未见过的组合，1-D 标签仍可能外推，但 InternViT 没见过那种拼接统计，OCR 会先碎。</p><p>生产上应把「纯文本请求是否短路视觉塔」做成显式开关：D 路径即使无图也载入 6B ViT，显存账与「骨干是 Qwen2-72B」不是同一句话。切格与 InternVL 同源，服务实现可以共用 tile 选择器，但 <code>&lt;tile_k&gt;</code> 的词表与模板必须跟 NVLM，不能复用另一家的 break token。文本回放若在继续训里被拿掉，视觉继续涨、代码掉点会立刻回来——这是解冻 LLM 的对称风险。</p><p><span class="marginnote">出处钉 Dai、Lee、Wang、Yang、Liu、Barker、Rintamaki、Shoeybi、Catanzaro、Ping，<em>NVLM: Open Frontier-Class Multimodal LLMs</em>，arXiv:2409.11402。项目页 research.nvidia.com/labs/adlr/NVLM-1。不要给 1.0 编造更新的会议号，也不要把后续未写入该 PDF 的型号倒填进 72B 层表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NVLM 1.0 在冻结 InternViT-6B 与 Qwen2-72B 上比较 D / X / H 三种融合，主发布权重是解码器专用 72B。</li><li>动态高分辨率用 448 切格、pixel shuffle 与一维 tile 标签；X 去掉 Perceiver，H 把缩略图与细格分路。</li><li>生产级多模态靠 SFT 混高质量文本，而不是只冻骨干；论文称文本数学与代码相对骨干上升。</li><li>D 赢在联合推理与 OCR 账单，X 赢在高分辨率吞吐，H 是折中，不是第三套视觉定律。</li><li>出处：Dai 等，<em>NVLM: Open Frontier-Class Multimodal LLMs</em>，arXiv:2409.11402。</li></ul>',12))])}const g=l(p,[["render",V]]);export{T as __pageData,g as default};
